import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"隱私權政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy.md","filePath":"zh-TW/guide/privacy.md","lastUpdated":1793173149000}`),a={name:`zh-TW/guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="隱私權政策" tabindex="-1">隱私權政策 <a class="header-anchor" href="#隱私權政策" aria-label="Permalink to “隱私權政策”">​</a></h1><p>Sudoku 是一款以離線優先為設計原則的應用程式，雲端功能均為選用。本頁說明 App 會蒐集哪些資料（若有），以及這些資料的用途。</p><h2 id="離線核心——遊玩過程不蒐集資料" tabindex="-1">離線核心——遊玩過程不蒐集資料 <a class="header-anchor" href="#離線核心——遊玩過程不蒐集資料" aria-label="Permalink to “離線核心——遊玩過程不蒐集資料”">​</a></h2><ul><li>核心解謎遊戲可完全離線遊玩，遊玩不需要任何網路存取。</li><li>所有遊戲資料——設定、遊戲狀態、鉛筆筆記與統計資料——都儲存在你的裝置本機。</li><li>沒有廣告、沒有分析工具，也沒有第三方追蹤 SDK。</li></ul><h2 id="選用的雲端功能" tabindex="-1">選用的雲端功能 <a class="header-anchor" href="#選用的雲端功能" aria-label="Permalink to “選用的雲端功能”">​</a></h2><h3 id="icloud-同步-cloudkit" tabindex="-1">iCloud 同步（CloudKit） <a class="header-anchor" href="#icloud-同步-cloudkit" aria-label="Permalink to “iCloud 同步（CloudKit）”">​</a></h3><p>當你登入 iCloud 並啟用同步時：</p><ul><li>遊戲存檔、統計資料、設定與每日挑戰進度會透過 Apple 的 CloudKit 服務，同步到你的個人 <strong>iCloud 帳號</strong>。</li><li>資料在傳輸過程與存放時，皆由 Apple 的基礎架構加密。</li><li>只有你能使用自己的 Apple ID 存取同步的資料。</li><li>此功能完全為選用——即使不啟用，App 仍可正常運作。</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>當你登入 Game Center 時：</p><ul><li>排行榜分數（各難度的最佳完成時間）可能會公開顯示於排行榜上。</li><li>成就進度由 Apple 的 Game Center 服務記錄。</li><li>你的 Game Center 顯示名稱會對排行榜上的其他玩家可見。</li><li>此功能完全為選用。</li></ul><h2 id="唯一的其他網路存取-「更多-app」" tabindex="-1">唯一的其他網路存取：「更多 App」 <a class="header-anchor" href="#唯一的其他網路存取-「更多-app」" aria-label="Permalink to “唯一的其他網路存取：「更多 App」”">​</a></h2><p>唯一的非雲端網路功能，是「設定」中選用的<strong>「更多 App」</strong>區塊，會從我們的伺服器取得一系列相關 App 的清單。此功能：</p><ul><li>僅在你前往「設定」→「更多 App」時才會啟用。</li><li>只取得輕量的 App 名稱與連結清單——不會傳送或儲存任何個人資料。</li><li>可以完全忽略，對遊戲體驗沒有任何影響。</li></ul><h2 id="我們不蒐集的資料" tabindex="-1">我們不蒐集的資料 <a class="header-anchor" href="#我們不蒐集的資料" aria-label="Permalink to “我們不蒐集的資料”">​</a></h2><ul><li>我們不蒐集個人資訊、檔案、影像或瀏覽記錄。</li><li>我們不會將任何遊戲資料傳送到外部伺服器（上述 iCloud／Game Center 的情形除外）。</li><li>我們未內含第三方分析或廣告 SDK。</li><li>我們不使用當機回報或遙測服務。</li></ul><h2 id="權限" tabindex="-1">權限 <a class="header-anchor" href="#權限" aria-label="Permalink to “權限”">​</a></h2><p>Sudoku 所需的權限極少：</p><ul><li><strong>iCloud</strong>（選用）：透過 CloudKit 在裝置間同步遊戲資料。</li><li><strong>Game Center</strong>（選用）：用於排行榜與成就。</li><li><strong>網路</strong>（選用）：用於 iCloud 同步、Game Center 與「更多 App」。</li></ul><p>本 App 不會要求定位、聯絡人、相機、麥克風或其他涉及隱私的權限。</p><h2 id="資料保留" tabindex="-1">資料保留 <a class="header-anchor" href="#資料保留" aria-label="Permalink to “資料保留”">​</a></h2><ul><li>本機資料會保留在你的裝置上，直到你解除安裝或重設 App。</li><li>透過 iCloud 同步的資料，依 Apple 的 iCloud 資料保留政策處理。</li><li>Game Center 資料依 Apple 的 Game Center 政策處理。</li></ul><h2 id="隱私權相關請求" tabindex="-1">隱私權相關請求 <a class="header-anchor" href="#隱私權相關請求" aria-label="Permalink to “隱私權相關請求”">​</a></h2><p>由於 Sudoku 將所有資料儲存在本機（或依你的選擇存放在個人 iCloud），我們並未控制或存取任何伺服器端資料。若要清除所有 App 資料：</p><ul><li>從你的裝置<strong>解除安裝 App</strong>。</li><li><strong>清除 iCloud 資料</strong>：在「設定」→［你的名字］→ iCloud →「管理帳號儲存空間」→ Sudoku →「刪除資料」。</li><li><strong>重設 Mac 本機資料</strong>：移除容器的操作說明請參閱疑難排解指南。</li></ul><h2 id="兒童隱私" tabindex="-1">兒童隱私 <a class="header-anchor" href="#兒童隱私" aria-label="Permalink to “兒童隱私”">​</a></h2><p>Sudoku 不會主動蒐集任何人的個人資訊，包括兒童。本 App 不需要帳號，也沒有聊天或社交功能。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to “聯絡我們”">​</a></h2><p>若對隱私有任何疑問，請在專案儲存庫提出 issue (<a href="https://github.com/sudoku-pro/sudoku-site" target="_blank" rel="noreferrer">https://github.com/sudoku-pro/sudoku-site</a>)，或寄信到 <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a> 與我們聯絡。</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};